package local.cotology.reader;

import org.junit.*;
import org.junit.rules.TemporaryFolder;
import org.json.*;
import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import static org.junit.Assert.*;

public class AudioTest {
    @Rule public TemporaryFolder temporary=new TemporaryFolder();
    static final String PROFILE="11111111-1111-4111-8111-111111111111",JOB="22222222-2222-4222-8222-222222222222",WORK="33333333-3333-4333-8333-333333333333",SERVER="https://my-pc.tail123.ts.net",HASH="a".repeat(64);
    static byte[] wave(){return wave(4410);}
    static byte[] wave(int frames){ByteBuffer b=ByteBuffer.allocate(44+frames*2).order(ByteOrder.LITTLE_ENDIAN);b.putInt(0x46464952).putInt(b.capacity()-8).putInt(0x45564157).putInt(0x20746d66).putInt(16).putShort((short)1).putShort((short)1).putInt(22050).putInt(44100).putShort((short)2).putShort((short)16).putInt(0x61746164).putInt(frames*2);for(int i=0;i<frames;i++)b.putShort((short)(Math.sin(i*0.1)*1000));return b.array();}
    static JSONObject manifest(byte[] bytes) throws Exception {return new JSONObject().put("schemaVersion",1).put("jobId",JOB).put("kind","audio").put("sourceSha256",HASH).put("recipeSha256",HASH).put("quality","technical-unlistened").put("workId",WORK).put("expressionId",WORK).put("editionId",WORK).put("segments",new JSONArray().put(new JSONObject().put("ordinal",0).put("sha256",AudioStore.hash(bytes)).put("bytes",bytes.length).put("mediaType","audio/wav").put("durationSeconds",0.2).put("sampleRate",22050).put("url",AudioStore.segmentPath(JOB,0))));}
    static JSONObject position(String hash) throws Exception {return new JSONObject().put("jobId",JOB).put("manifestSha256",hash).put("ordinal",0).put("seconds",0.12).put("rate",1.25).put("updatedAt",System.currentTimeMillis()).put("completed",false);}
    @Test public void audioAndPositionSurviveReopen() throws Exception {
        File root=temporary.newFolder();byte[] pcm=wave(),raw=manifest(pcm).toString().getBytes(StandardCharsets.UTF_8);AudioStore store=new AudioStore(root);JSONObject row=store.register(PROFILE,JOB,raw,AudioStore.hash(raw),"Книга","Автор");store.putChunk(PROFILE,JOB,0,pcm);store.recount(PROFILE,JOB,"partial",null);store.positionPut(PROFILE,JOB,position(row.getString("manifestSha256")));
        AudioStore reopened=new AudioStore(root);assertArrayEquals(pcm,reopened.chunk(PROFILE,JOB,0));assertEquals("complete",reopened.get(PROFILE,JOB).getString("status"));assertEquals(0.12,((JSONObject)reopened.positionGet(PROFILE,JOB)).getDouble("seconds"),0.00001);assertEquals(0.2,reopened.get(PROFILE,JOB).getDouble("totalDurationSeconds"),0.00001);
    }
    @Test public void manifestCannotRedirectOrChangeIdentity() throws Exception {
        byte[] pcm=wave();JSONObject m=manifest(pcm);m.getJSONArray("segments").getJSONObject(0).put("url","https://evil.org/test.wav");assertThrows(IOException.class,()->AudioStore.validateManifest(m.toString().getBytes(StandardCharsets.UTF_8),JOB));
        assertThrows(IOException.class,()->new AudioStore(temporary.newFolder()).get("../../other",JOB));assertThrows(IOException.class,()->AudioStore.segmentPath(JOB,-1));assertThrows(IOException.class,()->AudioStore.segmentPath(JOB,50000));
    }
    @Test public void corruptOrExecutablePayloadNeverPlays() throws Exception {
        byte[] pcm=wave();JSONObject segment=manifest(pcm).getJSONArray("segments").getJSONObject(0);pcm[55]^=1;assertThrows(IOException.class,()->AudioStore.validateWave(pcm,segment));
        byte[] appended=java.util.Arrays.copyOf(wave(),wave().length+4);ByteBuffer.wrap(appended).order(ByteOrder.LITTLE_ENDIAN).putInt(4,appended.length-8);JSONObject changed=new JSONObject(segment.toString()).put("bytes",appended.length).put("sha256",AudioStore.hash(appended));assertThrows(IOException.class,()->AudioStore.validateWave(appended,new JSONObject(segment.toString()).put("bytes",appended.length).put("sha256",AudioStore.hash(appended))));
        byte[] empty=wave();java.util.Arrays.fill(empty,44,empty.length,(byte)0);changed=new JSONObject(segment.toString()).put("sha256",AudioStore.hash(empty));JSONObject silence=changed;assertThrows(IOException.class,()->AudioStore.validateWave(empty,silence));
    }
    @Test public void staleOrInvalidPositionCannotReplaceSavedProgress() throws Exception {
        byte[] raw=manifest(wave()).toString().getBytes(StandardCharsets.UTF_8);AudioStore store=new AudioStore(temporary.newFolder());String hash=store.register(PROFILE,JOB,raw,null,"Книга","").getString("manifestSha256");store.positionPut(PROFILE,JOB,position(hash));assertThrows(IOException.class,()->store.positionPut(PROFILE,JOB,position(HASH)));assertThrows(IOException.class,()->store.positionPut(PROFILE,JOB,position(hash).put("seconds",900)));assertThrows(IOException.class,()->store.positionPut(PROFILE,JOB,position(hash).put("rate",3)));assertEquals(0.12,((JSONObject)store.positionGet(PROFILE,JOB)).getDouble("seconds"),0.0001);
    }
    @Test public void scopeCatalogRemainsOfflineAfterLogoutAndServerChange() throws Exception {
        class Fetcher implements AudioLibrary.Fetcher {String server=SERVER;byte[] pcm=wave(),raw=manifest(pcm).toString().getBytes(StandardCharsets.UTF_8);Fetcher() throws Exception{}public String currentServer(){return server;}public AudioLibrary.Response fetch(String host,String path,int max) throws Exception {if(path.equals("/api/me"))return new AudioLibrary.Response(new JSONObject().put("id",PROFILE).toString().getBytes(StandardCharsets.UTF_8),null);byte[] bytes=path.endsWith("/result")?raw:pcm;return new AudioLibrary.Response(bytes,AudioStore.hash(bytes));}}
        Fetcher fetcher=new Fetcher();AudioLibrary library=new AudioLibrary(temporary.newFolder(),fetcher);try{JSONObject row=library.register(new JSONObject().put("profileId",PROFILE).put("jobId",JOB).put("title","Офлайн"));String scope=row.getString("scopeId");library.download(scope,JOB);long deadline=System.currentTimeMillis()+4000;while(!library.get(scope,JOB).getString("status").equals("complete")&&System.currentTimeMillis()<deadline)Thread.sleep(25);assertEquals("complete",library.get(scope,JOB).getString("status"));fetcher.server="";JSONArray rows=library.list();assertEquals(1,rows.length());assertFalse(rows.getJSONObject(0).has("manifest"));assertArrayEquals(fetcher.pcm,library.chunk(scope,JOB,0,false));assertThrows(IOException.class,()->library.download(scope,JOB));assertTrue(library.url(scope,JOB,0).getBoolean("offline"));library.remove(scope,JOB);assertEquals(0,library.list().length());}finally{library.close();}
    }
    @Test public void symbolicLinksCannotEscapeStore() throws Exception {File root=temporary.newFolder(),outside=temporary.newFolder();try{Files.createSymbolicLink(new File(root,PROFILE).toPath(),outside.toPath());}catch(UnsupportedOperationException|IOException e){Assume.assumeNoException(e);}AudioStore store=new AudioStore(root);assertThrows(IOException.class,()->store.get(PROFILE,JOB));}
    @Test public void numbersAndUtf8AreStrict() throws Exception {JSONObject m=manifest(wave());m.getJSONArray("segments").getJSONObject(0).put("ordinal",0.5);JSONObject wrongFraction=m;assertThrows(IOException.class,()->AudioStore.validateManifest(wrongFraction.toString().getBytes(StandardCharsets.UTF_8),JOB));m=manifest(wave());m.getJSONArray("segments").getJSONObject(0).put("bytes","8864");JSONObject wrongType=m;assertThrows(IOException.class,()->AudioStore.validateManifest(wrongType.toString().getBytes(StandardCharsets.UTF_8),JOB));byte[] raw=manifest(wave()).toString().getBytes(StandardCharsets.UTF_8);raw[5]=(byte)0xff;assertThrows(java.nio.charset.CharacterCodingException.class,()->AudioStore.validateManifest(raw,JOB));}
    @Test public void changedSessionCannotPublishAnotherProfileDownload() throws Exception {AudioLibrary.Fetcher fetcher=new AudioLibrary.Fetcher(){public String currentServer(){return SERVER;}public AudioLibrary.Response fetch(String host,String path,int max) throws Exception {boolean me=path.equals("/api/me");return new AudioLibrary.Response((me?new JSONObject().put("id",PROFILE):manifest(wave())).toString().getBytes(StandardCharsets.UTF_8),null,me?"first-cookie":"second-cookie");}};AudioLibrary library=new AudioLibrary(temporary.newFolder(),fetcher);try{assertThrows(IOException.class,()->library.register(new JSONObject().put("profileId",PROFILE).put("jobId",JOB)));assertEquals(0,library.list().length());}finally{library.close();}}
    @Test public void cancellationPreservesPrefixAndResumeSkipsVerifiedChunks() throws Exception {
        class Fetcher implements AudioLibrary.Fetcher {final byte[] pcm=wave();final byte[] raw;final int[] count={0,0};final java.util.concurrent.CountDownLatch blocked=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);Fetcher() throws Exception{JSONObject m=manifest(pcm);m.getJSONArray("segments").put(new JSONObject(m.getJSONArray("segments").getJSONObject(0).toString()).put("ordinal",1).put("url",AudioStore.segmentPath(JOB,1)));raw=m.toString().getBytes(StandardCharsets.UTF_8);}public String currentServer(){return SERVER;}public AudioLibrary.Response fetch(String server,String path,int max) throws Exception {if(path.equals("/api/me"))return new AudioLibrary.Response(new JSONObject().put("id",PROFILE).toString().getBytes(StandardCharsets.UTF_8),null);if(path.endsWith("/result"))return new AudioLibrary.Response(raw,AudioStore.hash(raw));int ordinal=path.endsWith("/0")?0:1;count[ordinal]++;if(ordinal==1&&count[ordinal]==1){blocked.countDown();if(!release.await(3,java.util.concurrent.TimeUnit.SECONDS))throw new IOException("timeout");throw new IOException("cancelled");}return new AudioLibrary.Response(pcm,AudioStore.hash(pcm));}public void cancel(Thread thread){release.countDown();}}
        Fetcher fetcher=new Fetcher();AudioLibrary library=new AudioLibrary(temporary.newFolder(),fetcher);try{String scope=library.register(new JSONObject().put("profileId",PROFILE).put("jobId",JOB)).getString("scopeId");library.download(scope,JOB);assertTrue(fetcher.blocked.await(3,java.util.concurrent.TimeUnit.SECONDS));library.cancel(scope,JOB);long deadline=System.currentTimeMillis()+4000;while(library.get(scope,JOB).getString("status").equals("downloading")&&System.currentTimeMillis()<deadline)Thread.sleep(25);assertEquals(1,library.get(scope,JOB).getInt("downloadedSegments"));assertArrayEquals(fetcher.pcm,library.chunk(scope,JOB,0,false));library.download(scope,JOB);while(!library.get(scope,JOB).getString("status").equals("complete")&&System.currentTimeMillis()<deadline)Thread.sleep(25);assertEquals("complete",library.get(scope,JOB).getString("status"));assertEquals(1,fetcher.count[0]);assertEquals(2,fetcher.count[1]);}finally{library.close();}
    }
    @Test public void staleTimestampCannotRewindNewProgress() throws Exception {byte[] raw=manifest(wave()).toString().getBytes(StandardCharsets.UTF_8);AudioStore s=new AudioStore(temporary.newFolder());String hash=s.register(PROFILE,JOB,raw,null,"","").getString("manifestSha256");JSONObject saved=s.positionPut(PROFILE,JOB,position(hash).put("seconds",0.16));s.positionPut(PROFILE,JOB,position(hash).put("seconds",0.01).put("updatedAt",saved.getLong("updatedAt")-1000));assertEquals(0.16,((JSONObject)s.positionGet(PROFILE,JOB)).getDouble("seconds"),0.00001);}
    @Test public void corruptedOfflineCopyIsNotReportedAsComplete() throws Exception {File root=temporary.newFolder();AudioLibrary.Fetcher f=new AudioLibrary.Fetcher(){public String currentServer(){return SERVER;}public AudioLibrary.Response fetch(String server,String path,int max) throws Exception {byte[] raw=path.equals("/api/me")?new JSONObject().put("id",PROFILE).toString().getBytes(StandardCharsets.UTF_8):path.endsWith("/result")?manifest(wave()).toString().getBytes(StandardCharsets.UTF_8):wave();return new AudioLibrary.Response(raw,AudioStore.hash(raw));}};AudioLibrary lib=new AudioLibrary(root,f);try{String scope=lib.register(new JSONObject().put("profileId",PROFILE).put("jobId",JOB)).getString("scopeId");lib.chunk(scope,JOB,0,true);File file=new File(root,scope+"/data/"+PROFILE+"/"+JOB+"/00000.wav");byte[] raw=Files.readAllBytes(file.toPath());raw[50]^=1;Files.write(file.toPath(),raw);assertThrows(IOException.class,()->lib.chunk(scope,JOB,0,false));assertEquals("error",lib.get(scope,JOB).getString("status"));lib.chunk(scope,JOB,0,true);assertEquals("complete",lib.get(scope,JOB).getString("status"));}finally{lib.close();}}
    @Test public void transientServerLimitRetriesAutomaticallyWithoutResettingWork() throws Exception {class F implements AudioLibrary.Fetcher {int requests=0;public String currentServer(){return SERVER;}public AudioLibrary.Response fetch(String server,String path,int max) throws Exception {if(path.equals("/api/me"))return new AudioLibrary.Response(new JSONObject().put("id",PROFILE).toString().getBytes(StandardCharsets.UTF_8),null);if(path.endsWith("/result")){byte[] raw=manifest(wave()).toString().getBytes(StandardCharsets.UTF_8);return new AudioLibrary.Response(raw,AudioStore.hash(raw));}if(++requests==1)throw new AudioLibrary.RetryLater(1);return new AudioLibrary.Response(wave(),AudioStore.hash(wave()));}}F f=new F();AudioLibrary lib=new AudioLibrary(temporary.newFolder(),f);try{String scope=lib.register(new JSONObject().put("profileId",PROFILE).put("jobId",JOB)).getString("scopeId");lib.download(scope,JOB);long end=System.currentTimeMillis()+5000;while(!lib.get(scope,JOB).getString("status").equals("complete")&&System.currentTimeMillis()<end)Thread.sleep(25);assertEquals("complete",lib.get(scope,JOB).getString("status"));assertEquals(2,f.requests);}finally{lib.close();}}
    @Test public void integrityFailuresAreNotAutomaticallyRetried() throws Exception {class F implements AudioLibrary.Fetcher {int requests=0;public String currentServer(){return SERVER;}public AudioLibrary.Response fetch(String server,String path,int max) throws Exception {if(path.equals("/api/me"))return new AudioLibrary.Response(new JSONObject().put("id",PROFILE).toString().getBytes(StandardCharsets.UTF_8),null);if(path.endsWith("/result"))return new AudioLibrary.Response(manifest(wave()).toString().getBytes(StandardCharsets.UTF_8),null);requests++;byte[] corrupted=wave();corrupted[80]^=1;return new AudioLibrary.Response(corrupted,AudioStore.hash(corrupted));}}F f=new F();AudioLibrary lib=new AudioLibrary(temporary.newFolder(),f);try{String scope=lib.register(new JSONObject().put("profileId",PROFILE).put("jobId",JOB)).getString("scopeId");lib.download(scope,JOB);long end=System.currentTimeMillis()+3000;while(lib.get(scope,JOB).getString("status").equals("downloading")&&System.currentTimeMillis()<end)Thread.sleep(25);assertEquals("error",lib.get(scope,JOB).getString("status"));assertEquals(1,f.requests);assertEquals(0,lib.get(scope,JOB).getInt("downloadedSegments"));}finally{lib.close();}}
    @Test public void manifestCacheHasOneProcessWideByteBudgetAndEvictsOldEntries() throws Exception {
        String json=manifest(wave()).toString();byte[] padded=(" ".repeat(400000)+json).getBytes(StandardCharsets.UTF_8);AudioStore first=new AudioStore(temporary.newFolder());first.register(PROFILE,JOB,padded,null,"","");JSONObject firstParsed=first.get(PROFILE,JOB).getJSONObject("manifest");assertSame(firstParsed,first.get(PROFILE,JOB).getJSONObject("manifest"));
        for(int i=0;i<12;i++){AudioStore store=new AudioStore(temporary.newFolder());store.register(PROFILE,JOB,padded,null,"","");store.get(PROFILE,JOB);assertTrue(AudioStore.cachedManifestBytes()<=AudioStore.MANIFEST_CACHE_BYTES);assertTrue(AudioStore.cachedManifestCount()<=AudioStore.MANIFEST_CACHE_ENTRIES);}
        assertNotSame(firstParsed,first.get(PROFILE,JOB).getJSONObject("manifest"));
        byte[] large=(" ".repeat(AudioStore.MANIFEST_CACHE_BYTES)+json).getBytes(StandardCharsets.UTF_8);AudioStore uncached=new AudioStore(temporary.newFolder());uncached.register(PROFILE,JOB,large,null,"","");long before=AudioStore.cachedManifestBytes();JSONObject one=uncached.get(PROFILE,JOB).getJSONObject("manifest");assertNotSame(one,uncached.get(PROFILE,JOB).getJSONObject("manifest"));assertEquals(before,AudioStore.cachedManifestBytes());
    }
    @Test public void listReadsOnlyLightMetadataAndNeverParsesFullManifest() throws Exception {File root=temporary.newFolder();AudioStore store=new AudioStore(root);store.register(PROFILE,JOB,manifest(wave()).toString().getBytes(StandardCharsets.UTF_8),null,"","");Files.write(new File(root,PROFILE+"/"+JOB+"/manifest.json").toPath(),"not a manifest".getBytes(StandardCharsets.UTF_8));JSONArray rows=store.list(PROFILE);assertEquals(1,rows.length());assertFalse(rows.getJSONObject(0).has("manifest"));assertThrows(IOException.class,()->store.get(PROFILE,JOB));}
    @Test public void actualCompletionPersistsExactPcmEndAcrossColdReopen() throws Exception {
        int frames=143616;double exact=frames/22050.0,nativeMilliseconds=Math.floor(exact*1000)/1000;assertTrue(nativeMilliseconds<exact);
        File root=temporary.newFolder();byte[] pcm=wave(frames);JSONObject m=manifest(pcm);m.getJSONArray("segments").getJSONObject(0).put("durationSeconds",exact);byte[] raw=m.toString().getBytes(StandardCharsets.UTF_8);AudioStore store=new AudioStore(root);JSONObject row=store.register(PROFILE,JOB,raw,null,"Конец аудиокниги","");
        // The last sampled MediaPlayer counter can even be stale, as observed on
        // the real phone. Only its actual completion event establishes the end.
        store.positionPut(PROFILE,JOB,position(row.getString("manifestSha256")).put("seconds",5.248));
        JSONObject endpoint=AudioCompletion.position(row,0,1.25,System.currentTimeMillis());assertEquals(exact,endpoint.getDouble("seconds"),0);assertTrue(endpoint.getBoolean("completed"));
        store.positionPut(PROFILE,JOB,endpoint);JSONObject restored=(JSONObject)new AudioStore(root).positionGet(PROFILE,JOB);assertEquals(exact,restored.getDouble("seconds"),0);assertTrue(restored.getBoolean("completed"));assertEquals(0,restored.getInt("ordinal"));assertEquals(1.25,restored.getDouble("rate"),0);
    }
    @Test public void actualNonfinalCompletionPersistsNextSegmentWithoutRoundedTail() throws Exception {
        File root=temporary.newFolder();JSONObject m=manifest(wave());m.getJSONArray("segments").put(new JSONObject(m.getJSONArray("segments").getJSONObject(0).toString()).put("ordinal",1).put("url",AudioStore.segmentPath(JOB,1)));AudioStore store=new AudioStore(root);JSONObject row=store.register(PROFILE,JOB,m.toString().getBytes(StandardCharsets.UTF_8),null,"","");
        JSONObject endpoint=AudioCompletion.position(row,0,1,System.currentTimeMillis());assertEquals(1,endpoint.getInt("ordinal"));assertEquals(0,endpoint.getDouble("seconds"),0);assertFalse(endpoint.getBoolean("completed"));store.positionPut(PROFILE,JOB,endpoint);JSONObject restored=(JSONObject)new AudioStore(root).positionGet(PROFILE,JOB);assertEquals(1,restored.getInt("ordinal"));assertEquals(0,restored.getDouble("seconds"),0);assertFalse(restored.getBoolean("completed"));
    }
}
